def _local_search(gpu_num, placement, shared_kv, weighted_req_rate):
    """Plateau-capable hill climber over move/swap neighborhoods.

    Accepts any non-worsening move (new_max <= cur), not just strict
    improvements, so the search can traverse plateaus of equal max KVPR
    and escape configurations a strict climber gets stuck in. A bounded
    budget of accepted plateau/improving moves prevents cycling; the best
    state seen is snapshotted and restored at the end, so the caller never
    observes a regression.
    """
    EPS = 1e-12
    PLATEAU_BUDGET = 300  # max non-improving (equal-cost) moves accepted

    def _full_max():
        return max(_kvpr(weighted_req_rate[g], shared_kv[g]) for g in range(gpu_num))

    def _neighbor_max(g1, g2, w1, w2, m1, m2):
        others = max(_kvpr(weighted_req_rate[g], shared_kv[g])
                     for g in range(gpu_num) if g not in (g1, g2)) \
            if gpu_num > 2 else 0.0
        return max(_kvpr(w1, m1), _kvpr(w2, m2), others)

    def _record_best():
        return (max(_full_max(), 0.0),
                {g: list(ms) for g, ms in placement.items()},
                list(shared_kv), list(weighted_req_rate))

    best = _record_best()
    plateau_left = PLATEAU_BUDGET
    moved = True
    while moved:
        moved = False
        cur = _full_max()
        # try single-model moves
        for g1 in range(gpu_num):
            for model in list(placement[g1]):
                for g2 in range(gpu_num):
                    if g2 == g1:
                        continue
                    m2 = shared_kv[g2] + model.model_size
                    if m2 >= GPU_MEM_SIZE:
                        continue
                    w1 = weighted_req_rate[g1] - model.req_rate / model.slo
                    w2 = weighted_req_rate[g2] + model.req_rate / model.slo
                    m1 = shared_kv[g1] - model.model_size
                    new_max = _neighbor_max(g1, g2, w1, w2, m1, m2)
                    if new_max < cur - EPS or (new_max <= cur + EPS and plateau_left > 0):
                        placement[g1].remove(model)
                        placement[g2].append(model)
                        weighted_req_rate[g1], weighted_req_rate[g2] = w1, w2
                        shared_kv[g1], shared_kv[g2] = m1, m2
                        moved = True
                        if new_max < best[0] - EPS:
                            best = _record_best()
                            plateau_left = PLATEAU_BUDGET
                        elif new_max <= cur + EPS:
                            plateau_left -= 1
                        break
                if moved:
                    break
            if moved:
                break
        if not moved and plateau_left > 0:
            # try pairwise swaps between GPU pairs
            for g1 in range(gpu_num):
                for g2 in range(g1 + 1, gpu_num):
                    for a in placement[g1]:
                        for b in placement[g2]:
                            m1 = shared_kv[g1] - a.model_size + b.model_size
                            m2 = shared_kv[g2] - b.model_size + a.model_size
                            if m1 >= GPU_MEM_SIZE or m2 >= GPU_MEM_SIZE:
                                continue
                            ra, rb = a.req_rate / a.slo, b.req_rate / b.slo
                            w1 = weighted_req_rate[g1] - ra + rb
                            w2 = weighted_req_rate[g2] - rb + ra
                            new_max = _neighbor_max(g1, g2, w1, w2, m1, m2)
                            if new_max < cur - EPS or (new_max <= cur + EPS and plateau_left > 0):
                                placement[g1].remove(a)
                                placement[g2].remove(b)
                                placement[g1].append(b)
                                placement[g2].append(a)
